#!/usr/bin/env bash
# step42 — Add-to-Cart (combined order): floating cart + drawer, Add to cart on
# product pages, /cart review page, and a one-payment combined checkout that
# fulfils each item through the bot. New cart.js/cart.css keep app.js/app.css
# untouched. Reuses the existing orders flow (items stored on the order).
set -euo pipefail
APP=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BAK=$APP/.bak-step42-$TS
mkdir -p "$BAK"
echo "==> backup -> $BAK"

for f in routes/checkout.js views/order.ejs views/product.ejs views/partials/store_bottom.ejs; do
  mkdir -p "$BAK/$(dirname "$f")"; cp "$APP/$f" "$BAK/$f"
done

NEWFILES="public/js/cart.js public/css/cart.css views/cart.ejs views/checkout_cart.ejs"
restore(){
  echo "!! rolling back step42";
  for f in routes/checkout.js views/order.ejs views/product.ejs views/partials/store_bottom.ejs; do cp "$BAK/$f" "$APP/$f"; done
  for f in $NEWFILES; do rm -f "$APP/$f"; done
  pm2 restart gsz --update-env >/dev/null 2>&1 || true
}
trap 'restore' ERR

mkdir -p "$APP/public/js" "$APP/public/css" "$APP/views/partials" "$APP/routes"

writef(){
  local dest="$APP/$1" b64="$2" md5="$3"
  base64 -d "$b64" > "$dest"
  local got; got=$(md5sum "$dest" | awk '{print $1}')
  echo "   $1  $got $([ "$got" = "$md5" ] && echo OK || echo MISMATCH)"
  [ "$got" = "$md5" ] || { echo "!! md5 mismatch for $1"; false; }
}

# retry a GET until it contains a pattern (handles brand-new static files
# settling after restart). Up to ~10s per check.
getok(){ # url pattern label
  local i
  for i in 1 2 3 4 5 6 7 8; do
    if curl -fsS -m 10 "$1" 2>/dev/null | grep -q "$2"; then return 0; fi
    sleep 1
  done
  echo "!! $3"; return 1
}

cat > /tmp/s42_cartjs.b64 <<'B64_cartjs'

B64_cartjs
writef "public/js/cart.js" /tmp/s42_cartjs.b64 "5a0a1f760e8678588a9f0052e1a74b81"
rm -f /tmp/s42_cartjs.b64
cat > /tmp/s42_cartcss.b64 <<'B64_cartcss'

B64_cartcss
writef "public/css/cart.css" /tmp/s42_cartcss.b64 "19ef8a0d698f148e6c6ac494c6670134"
rm -f /tmp/s42_cartcss.b64
cat > /tmp/s42_cartejs.b64 <<'B64_cartejs'

B64_cartejs
writef "views/cart.ejs" /tmp/s42_cartejs.b64 "43eaab1c17b34f67e913be0932b2ac29"
rm -f /tmp/s42_cartejs.b64
cat > /tmp/s42_cocejs.b64 <<'B64_cocejs'

B64_cocejs
writef "views/checkout_cart.ejs" /tmp/s42_cocejs.b64 "09367215a8721a2bcb0b667668a3dfcf"
rm -f /tmp/s42_cocejs.b64
cat > /tmp/s42_orderejs.b64 <<'B64_orderejs'

B64_orderejs
writef "views/order.ejs" /tmp/s42_orderejs.b64 "30fc4175e2406333dbb53c1c54a29daf"
rm -f /tmp/s42_orderejs.b64
cat > /tmp/s42_productejs.b64 <<'B64_productejs'

B64_productejs
writef "views/product.ejs" /tmp/s42_productejs.b64 "0fc04987bca07848130fd26464c8224a"
rm -f /tmp/s42_productejs.b64
cat > /tmp/s42_sbejs.b64 <<'B64_sbejs'

B64_sbejs
writef "views/partials/store_bottom.ejs" /tmp/s42_sbejs.b64 "75f934ef3f5664bd95a58d75bceb65c0"
rm -f /tmp/s42_sbejs.b64
cat > /tmp/s42_cojs.b64 <<'B64_cojs'

B64_cojs
writef "routes/checkout.js" /tmp/s42_cojs.b64 "1cff2a4d36daa33ce297590a6334348e"
rm -f /tmp/s42_cojs.b64

echo "==> node --check"
node --check "$APP/routes/checkout.js"
node --check "$APP/public/js/cart.js"

echo "==> ejs compile checks"
node -e '
const ejs=require("/opt/gsz/node_modules/ejs"),fs=require("fs");
["views/cart.ejs","views/checkout_cart.ejs","views/order.ejs","views/product.ejs","views/partials/store_bottom.ejs"].forEach(function(f){
  ejs.compile(fs.readFileSync("/opt/gsz/"+f,"utf8"),{filename:"/opt/gsz/"+f});
  console.log("   compiled "+f);
});
'

echo "==> pm2 restart gsz"
pm2 restart gsz --update-env >/dev/null
sleep 4

echo "==> static assets (with retry)"
getok "http://127.0.0.1:3900/static/js/cart.js"  "GSZCart"     "cart.js not served" || false
getok "http://127.0.0.1:3900/static/css/cart.css" "gszcart-fab" "cart.css not served" || false

echo "==> home + product + cart pages"
HOME_HTML=$(curl -s -m 15 http://127.0.0.1:3900/)
printf '%s' "$HOME_HTML" | grep -q '</html>' || { echo "!! home broken"; false; }
printf '%s' "$HOME_HTML" | grep -q 'cart.js' || { echo "!! cart.js not injected site-wide"; false; }
SLUG=$(printf '%s' "$HOME_HTML" | grep -oE '/product/[a-z0-9-]+' | head -1 | sed 's#/product/##')
[ -n "$SLUG" ] || { echo "!! no product slug"; false; }
echo "   slug: $SLUG"

getok "http://127.0.0.1:3900/product/$SLUG" "Add to cart" "Add to cart button missing / product page broken" || false
getok "http://127.0.0.1:3900/cart" "cartPage" "/cart broken" || false

echo "==> POST a real cart to combined checkout"
CARTJSON='[{"slug":"'"$SLUG"'","planIdx":0,"qty":1}]'
CC=$(curl -s -m 15 -X POST http://127.0.0.1:3900/cart/checkout --data-urlencode "cart=$CARTJSON" --data-urlencode "region=PK")
printf '%s' "$CC" | grep -q '</html>' || { echo "!! combined checkout did not render"; false; }
printf '%s' "$CC" | grep -qi 'Cart checkout error:' && { echo "!! combined checkout threw"; false; } || true
printf '%s' "$CC" | grep -q 'Place order' || { echo "!! combined checkout missing submit"; false; }
printf '%s' "$CC" | grep -q 'pm-logo' || { echo "!! payment logos missing on combined checkout"; false; }
printf '%s' "$CC" | grep -qE 'name="proof"[^>]*required' || { echo "!! proof not required on combined checkout"; false; }

trap - ERR
echo "==> step42 OK — cart live. Backup: $BAK"
